SELECT
  R.*,
  P.PNAME AS pName,
  SI.PROFILE_IMG AS sellerProfileImg
FROM P_CHAT_ROOM R
JOIN PRODUCT P ON P.PRODUCT_NO = R.PRODUCT_NO
LEFT JOIN SELLER_INFO SI ON SI.USER_ID = R.SELLER_ID
WHERE R.PRODUCT_NO = #{productNo}
  AND R.BUYER_ID = #{buyerId}
  AND R.SELLER_ID = #{sellerId}

