INSERT INTO P_CHAT_ROOM 
(
  ROOM_ID, ORDER_ID, BUYER_ID, SELLER_ID, LAST_MESSAGE_ID, LAST_MESSAGE_AT, BUYER_LAST_READ_MESSAGE_ID,
  SELLER_LAST_READ_MESSAGE_ID, CDATETIME, UDATETIME, PRODUCT_NO
) VALUES 
(
  #{roomId}, #{orderId, jdbcType=NUMERIC}, #{buyerId}, #{sellerId}, NULL, NULL, NULL, NULL, SYSDATE, SYSDATE, #{productNo}
)

mapper.select:
SELECT R.ROOM_ID AS roomId, R.ORDER_ID AS orderId, R.BUYER_ID AS buyerId, R.SELLER_ID AS sellerId, R.PRODUCT_NO AS productNo,
P.PNAME AS pName,
/* ✅ 마지막 메시지 시간 = 메시지 테이블 MAX(CDATETIME) */ CAST(( SELECT MAX(M.CDATETIME) FROM P_CHAT_MESSAGE M WHERE M.ROOM_ID = R.ROOM_ID ) AS TIMESTAMP) AS lastMessageAt,
/* (옵션) 마지막 메시지 ID도 메시지 테이블 기준으로 맞추고 싶으면 */ ( SELECT MAX(M.MESSAGE_ID) FROM P_CHAT_MESSAGE M WHERE M.ROOM_ID = R.ROOM_ID ) AS lastMessageId,
R.CDATETIME AS cdatetime, R.UDATETIME AS udatetime
FROM P_CHAT_ROOM R JOIN USERS U ON U.USER_ID = #{userId} JOIN PRODUCT P ON P.PRODUCT_NO = R.PRODUCT_NO WHERE (U.USER_ROLE = 'BUYER' AND R.BUYER_ID = U.USER_ID) OR (U.USER_ROLE = 'SELLER' AND R.SELLER_ID = U.USER_ID)
/* ✅ 정렬도 “마지막 메시지 시간” 기준으로 */ ORDER BY CAST(( SELECT MAX(M.CDATETIME) FROM P_CHAT_MESSAGE M WHERE M.ROOM_ID = R.ROOM_ID ) AS TIMESTAMP) DESC

mapper.update:
UPDATE P_CHAT_ROOM
SET
  LAST_MESSAGE_ID = (
    SELECT MAX(MESSAGE_ID) FROM P_CHAT_MESSAGE WHERE ROOM_ID = #{roomId}
  ),
  LAST_MESSAGE_AT = (
    SELECT CAST(MAX(CDATETIME) AS TIMESTAMP) FROM P_CHAT_MESSAGE WHERE ROOM_ID = #{roomId}
  ),
  UDATETIME = SYSDATE
WHERE ROOM_ID = #{roomId}
